// Package gen writes a typed client for a vgraph schema: the code behind
// `vgraph gen`. It reads the schema the way the app does, by compiling a small
// program that registers every struct with an `edges()` method, and generates
// from what that program prints.
module gen

import json2
import os
import strings

// header starts every generated file, so `vgraph gen` knows which files it owns.
pub const header = '// Code generated by vgraph gen. DO NOT EDIT.'

// Entity is a struct that declares edges, found in the project's sources.
pub struct Entity {
pub:
	module_path string // the import path, such as `users.models`
	struct_name string // such as `User`
}

// alias is the name the generated code imports the entity's module as.
pub fn (e Entity) alias() string {
	return e.module_path.replace('.', '_')
}

// Column mirrors `vgraph.Column`, as the loader prints it.
pub struct Column {
pub:
	name         string
	field        string
	typ          string
	kind         string
	nullable     bool
	graphql_skip bool
	serial       bool
	optional     bool
	immutable    bool
	sensitive    bool
	unique       bool
	comment      string
	deprecated   string
	has_default  bool
	auto_update  bool
	type_name    string
	enum_values  []string
	embedded     string
	json_type    string
	// GraphQL options
	graphql_skip_in []string
	order_field     string
	directives      []string
}

const int_types = ['i8', 'i16', 'int', 'i64', 'u8', 'u16', 'u32', 'u64']
const float_types = ['f32', 'f64']

// base returns the column's V type without its option, such as `u32` or
// `enum`.
fn (c Column) base() string {
	return c.typ.trim_left('?')
}

// scalar reports whether the generator writes predicates, setters and orders
// for the column: a number, bool, string, time or enum.
fn (c Column) scalar() bool {
	b := c.base()
	return b in int_types || b in float_types || b in ['bool', 'string', 'time.Time', 'enum']
}

// numeric reports whether the column is a number: it can be added to, and
// aggregated.
fn (c Column) numeric() bool {
	return c.base() in int_types || c.base() in float_types
}

// ordered reports whether the column has `lt` / `gt` predicates.
fn (c Column) ordered() bool {
	return c.numeric() || c.base() == 'time.Time'
}

// v_type returns the column's V type as the generated code names it: an alias
// or enum of the model's module, or the base type.
fn (c Column) v_type(info Info) string {
	return if c.type_name != '' { '${info.entity.alias()}.${c.type_name}' } else { c.base() }
}

// to_prim returns the V expression `expr`, of the column's type, as an
// `orm.Primitive`'s value: an enum as its int, an alias as its base type.
fn (c Column) to_prim(expr string) string {
	if c.base() == 'enum' {
		return 'int(${expr})'
	}
	if c.type_name != '' {
		return '${c.base()}(${expr})'
	}
	return expr
}

// list returns the `load.in_<list>` the column's `in` predicates use, and how
// each value is converted for it ('' when not).
fn (c Column) list() (string, string) {
	b := c.base()
	return match true {
		b in ['i64', 'u64'] { 'i64s', if b == 'i64' && c.type_name == '' { '' } else { 'i64(it)' } }
		b == 'string' { 'strings', if c.type_name == '' { '' } else { 'string(it)' } }
		else { 'ints', if b == 'int' && c.type_name == '' { '' } else { 'int(it)' } }
	}
}

// v_type_name returns an alias's or enum's type name, or the base type.
fn (c Column) v_type_name() string {
	return if c.type_name != '' { c.type_name } else { c.base() }
}

// json_v_type returns a JSON field's V type as the generated code names it:
// the model module's types qualified, such as `[]articles_models.Tag`.
fn (c Column) json_v_type(info Info) string {
	mut out := ''
	mut word := ''
	for ch in c.json_type + ' ' {
		if ch.is_letter() || ch.is_digit() || ch == `_` || ch == `.` {
			word += ch.ascii_str()
			continue
		}
		if word.len > 0 && word[0].is_capital() && !word.contains('.') {
			out += '${info.entity.alias()}.${word}'
		} else {
			out += word
		}
		word = ''
		if ch != ` ` {
			out += ch.ascii_str()
		}
	}
	return out
}

// Edge mirrors `vgraph.Edge`, as the loader prints it.
pub struct Edge {
pub:
	name       string
	kind       string
	to         string
	column     string
	type_col   string
	type_val   string
	through    string
	through_to string
	soft_del   string
	ref        string
	unique     bool
	bidi       bool
	required   bool
	immutable  bool
	// GraphQL options
	graphql_skip bool
	order_field  string
	directives   []string
}

// Index mirrors `vgraph.Index`, as the loader prints it.
pub struct Index {
pub:
	name    string
	columns []string
	unique  bool
	where   string
}

// GraphqlTable mirrors `vgraph.GraphqlTable`, as the loader prints it.
pub struct GraphqlTable {
pub:
	type_name   string
	query_field string
	node        bool
	relay       bool
	mutations   []string = ['create', 'update', 'delete']
	directives  []string
}

// Table mirrors `vgraph.Table`, as the loader prints it.
pub struct Table {
pub:
	name         string
	struct_      string
	key          string
	columns      []Column
	edges        []Edge
	graphql_skip bool
	indexes      []Index
	view         bool
	hooks        int
	interceptors int
	rules        int
	graphql      GraphqlTable
	otel         Otel
}

// Otel mirrors `vgraph.Otel`, as the loader prints it: `level` is `none`,
// `ops`, `full` or `default`.
pub struct Otel {
pub:
	level string
}

fn (t Table) column(name string) !Column {
	for c in t.columns {
		if c.name == name {
			return c
		}
	}
	return error('`${t.name}` has no column `${name}`')
}

// discover returns the structs with an `edges() []vgraph.Edge` method in the
// project at `root`, sorted by module and name. It skips tests, hidden folders,
// the folders in `skip`, and folders that are projects of their own.
pub fn discover(root string, skip []string) ![]Entity {
	mut found := []Entity{}
	mut dirs := [root]
	for dirs.len > 0 {
		dir := dirs.pop()
		for name in os.ls(dir)! {
			path := os.join_path(dir, name)
			if os.is_dir(path) {
				if !name.starts_with('.') && name !in skip
					&& !os.exists(os.join_path(path, 'v.mod')) {
					dirs << path
				}
				continue
			}
			if !name.ends_with('.v') || name.ends_with('_test.v') {
				continue
			}
			for line in os.read_lines(path)! {
				struct_name := edges_receiver(line) or { continue }
				rel := dir.all_after(root).trim_left(os.path_separator)
				if rel == '' {
					return error('${path}: `${struct_name}` is in the main module, which the generated client cannot import; move it to a module')
				}
				found << Entity{
					module_path: rel.replace(os.path_separator, '.')
					struct_name: struct_name
				}
			}
		}
	}
	found.sort_with_compare(fn (a &Entity, b &Entity) int {
		ka := '${a.module_path}.${a.struct_name}'
		kb := '${b.module_path}.${b.struct_name}'
		return compare_strings(&ka, &kb)
	})
	return found
}

// edges_receiver returns `User` for a line such as
// `pub fn (u User) edges() []vgraph.Edge {`, and `none` for any other line.
fn edges_receiver(line string) ?string {
	text := line.trim_space()
	if !(text.starts_with('fn (') || text.starts_with('pub fn (')) {
		return none
	}
	receiver := text.all_after('(').all_before(')')
	rest := text.all_after(receiver + ')').replace(' ', '')
	if !rest.starts_with('edges()[]vgraph.Edge') {
		return none
	}
	name := receiver.fields().last().trim_left('&')
	return if name == '' { none } else { name }
}

// loader_source returns a program that registers `entities` with a schema,
// checks it, and prints its tables as JSON.
pub fn loader_source(entities []Entity) string {
	mut b := strings.new_builder(1024)
	b.writeln('module main\n')
	b.writeln('import json2')
	b.writeln('import five07.vgraph')
	for path in imports_of(entities) {
		b.writeln('import ${import_line(path)}')
	}
	b.writeln('\nfn main() {')
	b.writeln('\tmut schema := vgraph.Schema{}')
	for e in entities {
		b.writeln('\tschema.add[${e.alias()}.${e.struct_name}]() or { problems(err) }')
	}
	b.writeln('\tschema.validate() or { problems(err) }')
	b.writeln('\tprintln(json2.encode(schema.tables()))')
	b.writeln('}')
	b.writeln('\n// problems reports what is wrong with the schema, with the exit code 2.')
	b.writeln('fn problems(err IError) {')
	b.writeln('\teprintln(err.msg())')
	b.writeln('\texit(2)')
	b.writeln('}')
	return b.str()
}

fn imports_of(entities []Entity) []string {
	mut paths := []string{}
	for e in entities {
		if e.module_path !in paths {
			paths << e.module_path
		}
	}
	return paths
}

// import_line returns what follows `import` for the module `path`: the path,
// and the alias the generated code uses when it differs, as in
// `users.models as users_models`.
fn import_line(path string) string {
	alias := path.replace('.', '_')
	return if alias == path { path } else { '${path} as ${alias}' }
}

// decode_tables reads what the loader printed.
pub fn decode_tables(text string) ![]Table {
	return json2.decode[[]Table](text)!
}
